25	impl<'a> ReporterVisitor for ConsoleReporterVisitor<'a> {
26	    fn report_summary(
27	        &mut self,
28	        execution: &Execution,
29	        summary: TraversalSummary,
30	    ) -> io::Result<()> {
31	        if execution.is_check() && summary.suggested_fixes_skipped > 0 {
32	            self.0.log(markup! {
33	                <Warn>"Skipped "{summary.suggested_fixes_skipped}" suggested fixes.\n"</Warn>
34	                <Info>"If you wish to apply the suggested (unsafe) fixes, use the command "<Emphasis>"biome check --apply-unsafe\n"</Emphasis></Info>
35	            })
36	        }
37	
38	        if !execution.is_ci() && summary.diagnostics_not_printed > 0 {
39	            self.0.log(markup! {
40	                <Warn>"The number of diagnostics exceeds the number allowed by Biome.\n"</Warn>
41	                <Info>"Diagnostics not shown: "</Info><Emphasis>{summary.diagnostics_not_printed}</Emphasis><Info>"."</Info>
42	            })
43	        }
44	
45	        self.0.log(markup! {
46	            {ConsoleTraversalSummary(execution.traversal_mode(), &summary)}
47	        });
48	
49	        Ok(())
50	    }
51	
52	    fn report_diagnostics(
53	        &mut self,
54	        execution: &Execution,
55	        diagnostics_payload: DiagnosticsPayload,
56	    ) -> io::Result<()> {
57	        for diagnostic in &diagnostics_payload.diagnostics {
58	            if diagnostic.severity() >= diagnostics_payload.diagnostic_level {
59	                if diagnostic.tags().is_verbose() && diagnostics_payload.verbose {
60	                    self.0
61	                        .error(markup! {{PrintDiagnostic::verbose(diagnostic)}});
62	                } else {
63	                    self.0
64	                        .error(markup! {{PrintDiagnostic::simple(diagnostic)}});
65	                }
66	            }
67	            if execution.is_ci_github() {
68	                self.0
69	                    .log(markup! {{PrintGitHubDiagnostic::simple(diagnostic)}});
70	            }
71	        }
72	
73	        Ok(())
74	    }
75	}
